import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.D3GK3dQI.js";const h=JSON.parse('{"title":"ADR-003: Testing Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/003-testing-strategy.md","filePath":"adrs/003-testing-strategy.md"}'),n={name:"adrs/003-testing-strategy.md"};function r(o,e,l,c,d,g){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-003-testing-strategy" tabindex="-1">ADR-003: Testing Strategy <a class="header-anchor" href="#adr-003-testing-strategy" aria-label="Permalink to &quot;ADR-003: Testing Strategy&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-06<br><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A Kubernetes SRE/infrastructure component requires extreme reliability. Testing strategies that heavily rely on mocked Kubernetes clients often fail to catch actual schema mismatches or subtle informer caching issues.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We mandate a multi-tiered, highly effective testing strategy:</p><ol><li><p><strong>Integration Testing (<code>envtest</code>):</strong></p><ul><li>Informer startup, cache synchronization, and CRD integration SHOULD be tested using <code>sigs.k8s.io/controller-runtime/pkg/envtest</code> when test assets are available.</li></ul></li><li><p><strong>Unit Testing (Pure Logic):</strong></p><ul><li>Pure mapping functions, metric label generation, and Gateway API relationship logic MUST use idiomatic table-driven tests.</li><li>Kubernetes object graph tests MAY use controller-runtime&#39;s fake client, with the Gateway API types registered in the runtime scheme.</li></ul></li><li><p><strong>Metrics Contract Testing:</strong></p><ul><li>Prometheus collectors MUST be registered with a pedantic registry and gathered in tests.</li><li>Tests MUST verify the complete metric label set.</li></ul></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive:</strong> High confidence in production. Tests will catch API version skew issues early.</li><li><strong>Negative:</strong> Full <code>envtest</code> coverage requires additional local control-plane binaries and is slower than fake-client tests.</li></ul><h2 id="traceability" tabindex="-1">Traceability <a class="header-anchor" href="#traceability" aria-label="Permalink to &quot;Traceability&quot;">​</a></h2><p>All test files (<code>*_test.go</code>) MUST adhere to these rules and reference this document in their package or suite comments.</p><p>Manual end-to-end verification without a Gateway controller is documented in <code>docs/testing-on-kind.md</code>.</p>',12)])])}const p=t(n,[["render",r]]);export{h as __pageData,p as default};
